<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <meta name="theme-color" content="#f7f6f0">
  <title>Composition with Red, Blue and Yellow — Piet Mondrian</title>
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=DM+Sans:wght@400;500;600;700&display=swap" rel="stylesheet">
  <style>
    :root { --paper:#f7f6f0; --ink:#171717; --red:#d92b20; --blue:#164ca0; --yellow:#f2c51b; }
    * { box-sizing:border-box; }
    body { margin:0; background:var(--paper); color:var(--ink); font-family:'DM Sans',Arial,sans-serif; }
    .page { min-height:100svh; display:grid; grid-template-columns:minmax(310px, .9fr) minmax(400px,1.1fr); gap:clamp(32px,7vw,112px); align-items:center; max-width:1440px; margin:auto; padding:clamp(28px,5vw,72px); }
    .copy { max-width:520px; padding:32px 0; }
    .eyebrow, .meta-label, .index { font:500 11px 'DM Mono',monospace; letter-spacing:.14em; text-transform:uppercase; }
    .eyebrow { display:flex; gap:12px; align-items:center; margin:0 0 48px; }
    .eyebrow::before { content:''; width:30px; height:4px; background:var(--ink); }
    h1 { font-size:clamp(42px,5.1vw,76px); line-height:.99; letter-spacing:-.065em; font-weight:600; margin:0 0 25px; }
    h1 span { display:block; }
    .artist { font-size:17px; margin:0 0 36px; color:#50504b; }
    .artist strong { color:var(--ink); font-weight:600; }
    .intro { font-size:clamp(17px,1.55vw,21px); line-height:1.52; max-width:440px; margin:0 0 32px; }
    .details { display:flex; gap:32px; border-top:1px solid #c8c7c0; border-bottom:1px solid #c8c7c0; padding:18px 0; margin:0 0 30px; }
    .detail { display:grid; gap:7px; }
    .meta-label { color:#77766f; font-size:10px; }
    .meta-value { font-size:14px; font-weight:600; }
    .read { display:inline-flex; align-items:center; gap:18px; color:var(--ink); font-size:14px; font-weight:700; text-decoration:none; border-bottom:2px solid var(--ink); padding:0 0 8px; }
    .read .arrow { font-size:19px; transition:transform .2s; }
    .read:hover .arrow { transform:translateX(4px); }
    .read:focus-visible { outline:3px solid var(--blue); outline-offset:5px; }
    .art-wrap { position:relative; width:min(100%,670px); justify-self:end; }
    .art { aspect-ratio: .91 / 1; display:grid; grid-template-columns:1.03fr 2.65fr 2.8fr .48fr; grid-template-rows:.46fr 2.9fr 1.75fr .62fr; gap:10px; background:var(--ink); border:10px solid var(--ink); box-shadow:18px 20px 0 #e8e6dc; }
    .cell { background:white; }
    .top { grid-column:1 / 3; grid-row:1; }
    .red { background:var(--red); grid-column:3 / 5; grid-row:1 / 3; }
    .left { grid-column:1; grid-row:2 / 4; }
    .white-mid { grid-column:2; grid-row:2; }
    .white-right { grid-column:2 / 4; grid-row:3; }
    .blue { background:var(--blue); grid-column:1 / 3; grid-row:4; }
    .yellow { background:var(--yellow); grid-column:3 / 4; grid-row:4; }
    .edge { grid-column:4; grid-row:3 / 5; }
    .caption { margin:24px 0 0; display:flex; justify-content:space-between; gap:20px; color:#66655e; font:11px 'DM Mono',monospace; text-transform:uppercase; letter-spacing:.08em; }
    footer { position:fixed; bottom:18px; left:clamp(28px,5vw,72px); color:#8b8981; font:10px 'DM Mono',monospace; letter-spacing:.08em; text-transform:uppercase; }
    @media (max-width:820px) { .page { grid-template-columns:1fr; gap:50px; padding:30px 25px 68px; } .copy { padding:10px 0 0; } .eyebrow { margin-bottom:32px; } .art-wrap { justify-self:center; width:min(100%,560px); } footer { position:static; padding:0 25px 20px; } }
    @media (max-width:480px) { .details { gap:20px; } .art { gap:6px; border-width:7px; box-shadow:10px 12px 0 #e8e6dc; } .caption { font-size:9px; } }
